import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return an empty grid for a single live cell (dies of underpopulation) -- input [(0,0)] -> []");
  it.todo("should kill a live cell with 1 neighbor (underpopulation) -- input [(1,1),(0,1)] -> []");
  it.todo("should keep a live cell alive with 2 neighbors (survival)");
  it.todo("should keep a horizontal blinker cell alive with 2 neighbors and transition to vertical -- blinker Gen0 [(0,0),(0,1),(0,2)] -> Gen1 [(-1,1),(0,1),(1,1)]");
  it.todo("should keep every cell of a block still life alive -- [(0,0),(1,0),(0,1),(1,1)] -> unchanged");
  it.todo("should kill a live cell with 4 neighbors (overpopulation) -- center (1,1) with 4 neighbors dies -> grid ends with 8 cells, center dead");
  it.todo("should keep a live cell alive with 3 neighbors and create reproduction -- Rule 2 center survives + Rule 4 dead cell (1,1) becomes alive");
  it.todo("should reproduce a dead cell with exactly 3 neighbors -- Rule 4 example Gen0 [(0,0),(0,1),(1,0)] -> Gen1 includes (1,1)");
  it.todo("should handle the 3x3 overpopulation example -- Gen0 8 live cells (3x3 minus center) -> Gen1 4 live cells (4 corners) [center (1,1) has 4 neighbors and dies]");
  it.todo("should handle negative coordinates");
});

