import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it("should return an empty grid for a single live cell (dies of underpopulation) -- [(0,0)] -> []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });

  it("should kill live cells with fewer than 2 neighbors (Rule 1 underpopulation) -- [(0,1),(1,1)] -> []", () => {
    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
  });

  it("should keep a live cell alive with 2 neighbors (Rule 2 survival) -- blinker Gen0 [(0,0),(0,1),(0,2)] -> Gen1 [(-1,1),(0,1),(1,1)]", () => {
    expect(nextGeneration([[0, 0], [0, 1], [0, 2]])).toEqual([[-1, 1], [0, 1], [1, 1]]);
  });

  it("should keep a live cell alive with 3 neighbors (Rule 2 survival) -- center (1,1) of Rule 2 example survives", () => {
    expect(nextGeneration([[0, 0], [1, 0], [2, 0], [1, 2]])).toEqual([[0, 1], [1, 1], [2, 1], [1, 0], [1, 2]]);
  });

  it("should reproduce a dead cell with exactly 3 neighbors (Rule 4 reproduction) -- Rule 4 example Gen0 -> includes (1,1)", () => {
    expect(nextGeneration([[0, 0], [1, 0], [0, 1]])).toEqual([[0, 0], [1, 0], [0, 1], [1, 1]]);
  });

  it("should kill a live cell with more than 3 neighbors (Rule 3 overpopulation) -- center (1,1) of a full 3x3 minus center dies", () => {
    const fullMinusCenter = [[0, 0], [1, 0], [2, 0], [0, 1], [2, 1], [0, 2], [1, 2], [2, 2]];
    const result = nextGeneration(fullMinusCenter);
    expect(result).not.toContainEqual([1, 1]);
  });

  it("should produce the Rule 3 overpopulation example output -- Gen0 8 cells (3x3 minus center) -> Gen1 4 corner cells, no center", () => {
    const fullMinusCenter = [[0, 0], [1, 0], [2, 0], [0, 1], [2, 1], [0, 2], [1, 2], [2, 2]];
    expect(nextGeneration(fullMinusCenter)).toEqual([[0, 0], [2, 0], [0, 2], [2, 2]]);
  });

  it("should keep a block still life unchanged -- [(0,0),(1,0),(0,1),(1,1)] unchanged (all cells have 3 neighbors)", () => {
    const block = [[0, 0], [1, 0], [0, 1], [1, 1]];
    expect(nextGeneration(block)).toEqual(block);
  });

  it("should handle negative coordinates -- pentomino moving pattern", () => {
    const cells = [[-1, -1], [0, -1], [1, -1], [-1, 0], [0, 0]];
    const result = nextGeneration(cells);
    expect(result).toEqual([[-2, -1], [2, -1], [0, 0], [1, 1], [0, -2]]);
  });
});

import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it("should return an empty grid for a single live cell (dies of underpopulation) -- [(0,0)] -> []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });

  it("should kill live cells with fewer than 2 neighbors (Rule 1 underpopulation) -- [(0,1),(1,1)] -> []", () => {
    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
  });

  it("should transition the blinker vertical -> horizontal (Rule 2 survival + Rule 4 reproduction) -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]", () => {
    expect(nextGeneration([[0, 0], [0, 1], [0, 2]])).toEqual([[-1, 1], [0, 1], [1, 1]]);
  });

  it("should keep a block still life unchanged (survival) -- [(0,0),(1,0),(0,1),(1,1)] unchanged", () => {
    const block = [[0, 0], [1, 0], [0, 1], [1, 1]];
    expect(nextGeneration(block)).toEqual(block);
  });

  it("should reproduce a dead cell with exactly 3 neighbors (Rule 4) -- [(0,0),(1,0),(0,1)] -> 4 cells including (1,1)", () => {
    expect(nextGeneration([[0, 0], [1, 0], [0, 1]])).toEqual([[0, 0], [1, 0], [0, 1], [1, 1]]);
  });

  it("should kill a live cell with more than 3 neighbors (Rule 3 overpopulation) -- center (1,1) of full 3x3 minus center dies", () => {
    const ring = [[0, 0], [1, 0], [2, 0], [0, 1], [2, 1], [0, 2], [1, 2], [2, 2]];
    expect(nextGeneration(ring)).toEqual([[0, 0], [2, 0], [0, 2], [2, 2]]);
  });

  it("should handle negative coordinates -- a single negative cell dies -- [(-3,-2)] -> []", () => {
    expect(nextGeneration([[-3, -2]])).toEqual([]);
  });

  it("should handle negative coordinates in a live pattern -- blinker at negative origin transitions", () => {
    expect(nextGeneration([[-1, -1], [-1, 0], [-1, 1]])).toEqual([[-2, 0], [-1, 0], [0, 0]]);
  });
});

export type Cell = [number, number];

const key = (x: number, y: number) => `${x},${y}`;

export function nextGeneration(cells: Cell[]): Cell[] {
  const live = new Set(cells.map(([x, y]) => key(x, y)));

  const neighbors = (x: number, y: number) => [
    [x - 1, y - 1], [x, y - 1], [x + 1, y - 1],
    [x - 1, y], [x + 1, y],
    [x - 1, y + 1], [x, y + 1], [x + 1, y + 1],
  ];

  const liveCount = (x: number, y: number) =>
    neighbors(x, y).filter(([nx, ny]) => live.has(key(nx, ny))).length;

  const candidates = new Set<string>();
  cells.forEach(([x, y]) => {
    neighbors(x, y).forEach(([nx, ny]) => candidates.add(key(nx, ny)));
    candidates.add(key(x, y));
  });

  const next: Cell[] = [];
  candidates.forEach((k) => {
    const [x, y] = k.split(",").map(Number);
    const count = liveCount(x, y);
    if (live.has(k)) {
      if (count === 2 || count === 3) next.push([x, y]);
    } else {
      if (count === 3) next.push([x, y]);
    }
  });

  return next;
}

